const requestBody = $('Email draft request').first().json.body || {};
const classifierOutput = $('Email classifier agent').first().json;

function extractModelText(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const extracted = extractModelText(item);
      if (extracted) return extracted;
    }
    return '';
  }
  if (!value || typeof value !== 'object') return '';
  if (typeof value.output === 'string') return value.output;
  if (typeof value.text === 'string') return value.text;
  if (typeof value.output_text === 'string') return value.output_text;
  if (typeof value.content === 'string') return value.content;
  if (Array.isArray(value.content)) return extractModelText(value.content);
  if (Array.isArray(value.output)) return extractModelText(value.output);
  if (value.message) return extractModelText(value.message);
  if (value.response) return extractModelText(value.response);
  return '';
}

function parseJson(value) {
  const raw = extractModelText(value).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  if (!raw) return {};
  try { return JSON.parse(raw); } catch { return {}; }
}

const subjectText = String(requestBody.subject || '').toLowerCase();
const bodyText = String(requestBody.body_text || requestBody.bodyText || '').toLowerCase();
const fullText = `${subjectText}\n${bodyText}`;
const nonActionablePattern = /(newsletter|unsubscribe|no[- ]?reply|noreply|mailer-daemon|delivery status notification|undelivered mail|out of office|fuera de la oficina|resposta autom[aà]tica|respuesta autom[aá]tica)/i;
const actionablePattern = /(\?|\bhorari|\bhorarios|\bhoraire|\bopening hours|\bentrad|\bticket|\bprecio|\bpreu|\bprice|\bdescompte|\bdescuento|\bdiscount|\bgrupo|\bgrup|\bgroup|\baccessibil|\bubicaci|\bdirecci|\bprogramaci|\bcartelera|\bagenda|\bvisita|\bcontact|\bdevoluci|\brefund|\bvoldria|\bqueria|\bquisiera|\bcan you|\bcould you|\bhi ha|\bhay|\bteniu|\bten[eé]is)/i;
const isNonActionable = nonActionablePattern.test(fullText) && !actionablePattern.test(fullText);
const isActionable = actionablePattern.test(fullText) || bodyText.trim().length > 20;

const parsed = parseJson(classifierOutput);
let shouldProcess = parsed.should_process !== undefined ? Boolean(parsed.should_process) : Boolean(parsed.shouldProcess ?? true);
let shouldReply = parsed.should_reply !== undefined ? Boolean(parsed.should_reply) : Boolean(parsed.shouldReply ?? shouldProcess);
if (isActionable && !isNonActionable) {
  shouldProcess = true;
  shouldReply = true;
}
if (isNonActionable) {
  shouldProcess = false;
  shouldReply = false;
}

const topic = parsed.topic || parsed.category || (fullText.match(/horari|horarios/) ? 'horarios' : 'otro');
const priority = ['low', 'normal', 'high', 'urgent'].includes(parsed.priority) ? parsed.priority : 'normal';

return [{
  json: {
    should_process: shouldProcess,
    should_reply: shouldReply,
    needs_human_review: Boolean(parsed.needs_human_review || parsed.needsHumanReview),
    classification_reason: parsed.classification_reason || parsed.classificationReason || (shouldProcess ? 'visitor_question' : 'non_actionable'),
    topic,
    priority,
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : null,
    escalation_reason: parsed.escalation_reason || parsed.escalationReason || null,
    request: requestBody,
    talia_config: $('Fetch TALIA email config').first().json,
    raw_classifier_output: classifierOutput
  }
}];

const classification = $('Normalize classification').first().json;
return [{
  json: {
    should_process: Boolean(classification.should_process),
    should_reply: false,
    classification_reason: classification.classification_reason,
    subject: null,
    body_text: null,
    body_html: null,
    topic: classification.topic || 'otro',
    priority: classification.priority || 'normal',
    confidence: classification.confidence,
    escalation_reason: classification.escalation_reason,
    needs_human_review: classification.needs_human_review,
    classification
  }
}];

