const classification = $('Normalize classification').first().json;
const requestBody = $('Email draft request').first().json.body || {};
const draftOutput = $('Email draft agent').first().json;

function extractModelText(value) {
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const extracted = extractModelText(item);
      if (extracted) return extracted;
    }
    return '';
  }
  if (!value || typeof value !== 'object') return '';
  if (typeof value.output === 'string') return value.output;
  if (typeof value.text === 'string') return value.text;
  if (typeof value.output_text === 'string') return value.output_text;
  if (typeof value.content === 'string') return value.content;
  if (Array.isArray(value.content)) return extractModelText(value.content);
  if (Array.isArray(value.output)) return extractModelText(value.output);
  if (value.message) return extractModelText(value.message);
  if (value.response) return extractModelText(value.response);
  return '';
}

function parseJson(value) {
  const raw = extractModelText(value).replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
  if (!raw) return {};
  try { return JSON.parse(raw); } catch {
    return { body_text: raw };
  }
}

const parsed = parseJson(draftOutput);
const fallbackBody = 'Hola, gracias por contactar. Hemos recibido tu consulta y te dejamos este borrador para revisión del equipo de atención. Si necesitas una respuesta más precisa, revisa la información del cliente antes de enviar.';
const subject = parsed.subject || (requestBody.subject ? `Re: ${requestBody.subject}` : null);
const bodyText = parsed.body_text || parsed.bodyText || parsed.body || parsed.reply || fallbackBody;
const priority = ['low', 'normal', 'high', 'urgent'].includes(parsed.priority) ? parsed.priority : (classification.priority || 'normal');

return [{
  json: {
    should_process: classification.should_process,
    should_reply: true,
    classification_reason: classification.classification_reason,
    subject,
    body_text: bodyText,
    body_html: parsed.body_html || parsed.bodyHtml || null,
    topic: parsed.topic || classification.topic || 'otro',
    priority,
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : classification.confidence,
    escalation_reason: parsed.escalation_reason || parsed.escalationReason || classification.escalation_reason || null,
    needs_human_review: classification.needs_human_review,
    classification,
    raw_draft_output: draftOutput
  }
}];
